const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometries
  const robinsonCrusoe = ee.Geometry.Point([-78.84, -33.64]);
  const santaClara = ee.Geometry.Point([-78.82, -33.75]);
  const dateStart = '2018-11-01';
  const dateEnd = '2018-11-30';

  // 2. Load Sentinel-2 collection
  let col = ee.ImageCollection('COPERNICUS/S2')
    .filterDate(dateStart, dateEnd)
    .filterBounds(robinsonCrusoe.buffer(5000))
    .filterMetadata('CLOUDY_PIXEL_PERCENTAGE', 'less_than', 50);

  let count = col.size().getInfo();

  // Check for empty collection
  if (count === 0) {
    console.log('Sentinel-2 No images found in Nov 2018 for Robinson Crusoe.');
    // Try Landsat 8 fallback
    col = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterDate(dateStart, dateEnd)
      .filterBounds(robinsonCrusoe.buffer(5000));
    count = col.size().getInfo();
    if (count === 0) {
      console.log('Landsat 8 also empty.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  console.log('Images found: ' + count);

  // 3. Function to calculate NDVI
  function calcNDVI(img) {
    // For Sentinel-2
    if (img.bandNames().contains('B4').getInfo && img.bandNames().contains('B4').getInfo()) {
      const ndvi = img.normalizedDifference(['B8', 'B4']).rename('NDVI');
      const mask = img.select('QA60').lt(1024); // Mask clouds
      return ndvi.updateMask(mask);
    } else {
      // For Landsat 8
      const ndvi = img.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI');
      const qa = img.select('QA_PIXEL');
      const mask = qa.bitwiseAnd(32).eq(0).and(qa.bitwiseAnd(8).eq(0)); // Remove clouds/shadows
      return ndvi.updateMask(mask);
    }
  }

  // 4. Calculate NDVI for Robinson Crusoe
  const ndvi_rc = col.map(calcNDVI).mean();
  const stats_rc = ndvi_rc.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), null, true),
    geometry: robinsonCrusoe.buffer(5000),
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const val_rc = stats_rc.NDVI;
  const pix_rc = stats_rc['NDVI_count'];

  // Check for valid pixels
  if (pix_rc === 0 || pix_rc === null) {
    console.log('RC No valid pixels after masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 5. Calculate NDVI for Santa Clara (expand search area)
  let col_sc = ee.ImageCollection('COPERNICUS/S2')
    .filterDate(dateStart, dateEnd)
    .filterBounds(santaClara.buffer(5000))
    .filterMetadata('CLOUDY_PIXEL_PERCENTAGE', 'less_than', 50);

  if (col_sc.size().getInfo() === 0) {
    col_sc = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterDate(dateStart, dateEnd)
      .filterBounds(santaClara.buffer(5000));
  }

  if (col_sc.size().getInfo() === 0) {
    console.log('SC No images found.');
    console.log('<answer>C1</answer>');
    return;
  }

  const ndvi_sc = col_sc.map(calcNDVI).mean();
  const stats_sc = ndvi_sc.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), null, true),
    geometry: santaClara.buffer(5000),
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const val_sc = stats_sc.NDVI;
  const pix_sc = stats_sc['NDVI_count'];

  if (pix_sc === 0 || pix_sc === null) {
    console.log('SC No valid pixels after masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 6. Validate results
  if (val_rc === null || val_sc === null || val_rc === undefined || val_sc === undefined) {
    console.log('Invalid NDVI calculation result.');
    console.log('<answer>C3</answer>');
    return;
  }

  if (val_rc < -1 || val_rc > 1 || val_sc < -1 || val_sc > 1) {
    console.log('NDVI out of valid range [-1, 1].');
    console.log('<answer>C3</answer>');
    return;
  }

  // 7. Final comparison
  console.log('RC NDVI: ' + val_rc.toFixed(3) + ' (pixels: ' + pix_rc + ')');
  console.log('SC NDVI: ' + val_sc.toFixed(3) + ' (pixels: ' + pix_sc + ')');

  if (val_rc > val_sc) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
